// Times sets number of times cameraRequests.Vote should be invoked
func (mmVote *mCameraRequestsMockVote) Times(n uint64) *mCameraRequestsMockVote {
	if n == 0 {
		mmVote.mock.t.Fatalf("Times of CameraRequestsMock.Vote mock can not be zero")
	}
	mm_atomic.StoreUint64(&mmVote.expectedInvocations, n)
	mmVote.expectedInvocationsOrigin = minimock.CallerInfo(1)
	return mmVote
}

func (mmVote *mCameraRequestsMockVote) invocationsDone() bool {
	if len(mmVote.expectations) == 0 && mmVote.defaultExpectation == nil && mmVote.mock.funcVote == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmVote.mock.afterVoteCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmVote.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// Vote implements mm_implementation.cameraRequests
func (mmVote *CameraRequestsMock) Vote(ctx context.Context, o models.VoteCameraRequestOpts) (c2 models.CameraRequest, err error) {
	mm_atomic.AddUint64(&mmVote.beforeVoteCounter, 1)
	defer mm_atomic.AddUint64(&mmVote.afterVoteCounter, 1)

	mmVote.t.Helper()

	if mmVote.inspectFuncVote != nil {
		mmVote.inspectFuncVote(ctx, o)
	}

	mm_params := CameraRequestsMockVoteParams{ctx, o}

	// Record call args
	mmVote.VoteMock.mutex.Lock()
	mmVote.VoteMock.callArgs = append(mmVote.VoteMock.callArgs, &mm_params)
	mmVote.VoteMock.mutex.Unlock()

	for _, e := range mmVote.VoteMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.c2, e.results.err
		}
	}

	if mmVote.VoteMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmVote.VoteMock.defaultExpectation.Counter, 1)
		mm_want := mmVote.VoteMock.defaultExpectation.params
		mm_want_ptrs := mmVote.VoteMock.defaultExpectation.paramPtrs

		mm_got := CameraRequestsMockVoteParams{ctx, o}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmVote.t.Errorf("CameraRequestsMock.Vote got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmVote.VoteMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.o != nil && !minimock.Equal(*mm_want_ptrs.o, mm_got.o) {
				mmVote.t.Errorf("CameraRequestsMock.Vote got unexpected parameter o, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmVote.VoteMock.defaultExpectation.expectationOrigins.originO, *mm_want_ptrs.o, mm_got.o, minimock.Diff(*mm_want_ptrs.o, mm_got.o))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmVote.t.Errorf("CameraRequestsMock.Vote got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmVote.VoteMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmVote.VoteMock.defaultExpectation.results
		if mm_results == nil {
			mmVote.t.Fatal("No results are set for the CameraRequestsMock.Vote")
		}
		return (*mm_results).c2, (*mm_results).err
	}
	if mmVote.funcVote != nil {
		return mmVote.funcVote(ctx, o)
	}
	mmVote.t.Fatalf("Unexpected call to CameraRequestsMock.Vote. %v %v", ctx, o)
	return
}

// VoteAfterCounter returns a count of finished CameraRequestsMock.Vote invocations
func (mmVote *CameraRequestsMock) VoteAfterCounter() uint64 {
	return mm_atomic.LoadUint64(&mmVote.afterVoteCounter)
}

// VoteBeforeCounter returns a count of CameraRequestsMock.Vote invocations
func (mmVote *CameraRequestsMock) VoteBeforeCounter() uint64 {
	return mm_atomic.LoadUint64(&mmVote.beforeVoteCounter)
}

// Calls returns a list of arguments used in each call to CameraRequestsMock.Vote.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmVote *mCameraRequestsMockVote) Calls() []*CameraRequestsMockVoteParams {
	mmVote.mutex.RLock()

	argCopy := make([]*CameraRequestsMockVoteParams, len(mmVote.callArgs))
	copy(argCopy, mmVote.callArgs)

	mmVote.mutex.RUnlock()

	return argCopy
}

// MinimockVoteDone returns true if the count of the Vote invocations corresponds
// the number of defined expectations
func (m *CameraRequestsMock) MinimockVoteDone() bool {
	if m.VoteMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.VoteMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.VoteMock.invocationsDone()
}

// MinimockVoteInspect logs each unmet expectation
func (m *CameraRequestsMock) MinimockVoteInspect() {
	for _, e := range m.VoteMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to CameraRequestsMock.Vote at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterVoteCounter := mm_atomic.LoadUint64(&m.afterVoteCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.VoteMock.defaultExpectation != nil && afterVoteCounter < 1 {
		if m.VoteMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to CameraRequestsMock.Vote at\n%s", m.VoteMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to CameraRequestsMock.Vote at\n%s with params: %#v", m.VoteMock.defaultExpectation.expectationOrigins.origin, *m.VoteMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcVote != nil && afterVoteCounter < 1 {
		m.t.Errorf("Expected call to CameraRequestsMock.Vote at\n%s", m.funcVoteOrigin)
	}

	if !m.VoteMock.invocationsDone() && afterVoteCounter > 0 {
		m.t.Errorf("Expected %d calls to CameraRequestsMock.Vote at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.VoteMock.expectedInvocations), m.VoteMock.expectedInvocationsOrigin, afterVoteCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *CameraRequestsMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockListInspect()

			m.MinimockSetStatusInspect()

			m.MinimockSubmitInspect()

			m.MinimockVoteInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *CameraRequestsMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *CameraRequestsMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockListDone() &&
		m.MinimockSetStatusDone() &&
		m.MinimockSubmitDone() &&
		m.MinimockVoteDone()
}
